test('secondary dialogs retain a supported user choice when switching models and map pixel dimensions',opts,async()=>{
 const {dom,q}=studio();q.initRetryDialog();
 const schemas={standard:{properties:{aspect_ratio:{enum:['1:1','3:4','16:9']},resolution:{enum:['1K','2K']}}},pixels:{properties:{size:{enum:['1024*1024','1536*2048','1920*1080']}}},resolutionPixels:{properties:{resolution:{enum:['1024*1024','1536*2048','1920*1080']}}}};
 q.meta.models=Object.keys(schemas).map(name=>({name,display_name:name,selected:true}));q.schema=async name=>schemas[name];
 q.retrySource={payload:{aspect_ratio:'3:4',resolution:'2K'}};
 try{
  for(const prefix of ['reference-','pose-','edit-','retry-']){
   q.fillModels(prefix+'model','standard');q.$(prefix+'ratio').dataset.desired='16:9';await q.modelSettings(prefix);
   q.$(prefix+'ratio').value='3:4';q.$(prefix+'ratio').onchange();q.$(prefix+'resolution').value='1K';q.$(prefix+'resolution').onchange();
   await q.modelSettings(prefix);assert.equal(q.$(prefix+'ratio').value,'3:4');assert.equal(q.$(prefix+'resolution').value,'1K');
   for(const model of ['pixels','resolutionPixels']){
    q.$(prefix+'ratio').value='3:4';q.$(prefix+'ratio').onchange();
    q.$(prefix+'model').value=model;await q.modelSettings(prefix);
    assert.equal(q.$(prefix+'ratio').value,'3:4');assert.equal(q.$(prefix+'resolution').value,'1536*2048');
    q.$(prefix+'ratio').value='16:9';q.$(prefix+'ratio').onchange();assert.equal(q.$(prefix+'resolution').value,'1920*1080');
    const payload=q.optionPayload(prefix);assert.equal(payload.aspect_ratio,'16:9');assert.equal(model==='pixels'?payload.size:payload.resolution,'1920*1080');
   }
   q.$(prefix+'model').value='standard';await q.modelSettings(prefix);assert.equal(q.$(prefix+'ratio').value,'16:9');assert.equal(q.optionPayload(prefix).size,undefined);
  }
 }finally{dom.window.close();}
});
