test('task failure details show structured provider code and message safely',opts,()=>{const {dom,q}=studio();q.jobs=[{id:'failed',state:'failed',payload:{model:'model',prompt:'保留原文',refs:[]},result:{source:'Lovart',error:{code:'API_CONTENT_POLICY',message:'Provider filtered <image>'}},events:[],task_ids:['provider-id']}];q.openJob('failed');const text=q.$('job-content').textContent;assert.match(text,/API_CONTENT_POLICY/);assert.match(text,/Provider filtered <image>/);assert.equal(q.$('job-content').querySelector('image'),null);dom.window.close();});
test('retry starts in a review dialog with original prompt and does not submit until confirmed',opts,async()=>{const {dom,q}=studio();q.jobs=[{id:'failed',state:'failed',payload:{model:'model',prompt:'原始提示词',refs:[],aspect_ratio:'3:4',resolution:'2K'},events:[]}];q.meta.models=[{name:'model',display_name:'Model',capabilities:['generate']}];q.modelSettings=async()=>{};q.submit=async()=>{throw Error('must not submit on opening');};await q.openRetryJob('failed');assert.equal(q.$('retry-dialog').open,true);assert.equal(q.$('retry-prompt').value,'原始提示词');assert.match(q.$('retry-dialog').textContent,/平台额度/);dom.window.close();});
test('edit model list excludes models without declared edit capability',opts,async()=>{const {dom,q}=studio();q.assets=[{id:'work',role:'output',name:'作品',model:'reference-only'}];q.meta.connection.executor='external';q.meta.models=[{name:'reference-only',display_name:'Reference',capabilities:['generate','references']},{name:'editable',display_name:'Editable',capabilities:['generate','references','edit']}];q.modelSettings=async()=>{};await q.openEdit('work');assert.equal(q.$('edit-model').value,'editable');assert.equal(q.$('edit-model').options.length,1);dom.window.close();});
test('English edit dialog retains original image name and shows instructions',opts,async()=>{const {dom,w,q}=studio();w.MuseLanguage=require('../static/i18n.js');w.eval(fs.readFileSync(path.join(staticDir,'i18n-runtime.js'),'utf8'));q.i18n=await w.MuseLanguageRuntime.prepare({document:w.document,storage:w.localStorage,languages:['en'],fetchCatalog:async()=>require('../static/i18n-catalog.json')});q.assets=[{id:'work',role:'output',name:'我的作品',model:'editable'}];q.meta.models=[{name:'editable',display_name:'Editable'}];q.modelSettings=async()=>{};await q.openEdit('work');assert.match(q.$('edit-target').textContent,/我的作品/);assert.match(q.$('edit-target').textContent,/original is kept/i);assert.match(q.$('edit-dialog').textContent,/Describe what you want to change/);assert.equal(q.$('edit-prompt').value,'');dom.window.close();});
test('completed pose observation can be restored without starting another analysis',opts,async()=>{const {dom,q}=studio();q.poseProject='A';q.poseAnalysisResults=[{id:'observation',asset_id:'pose-asset',state:'completed',result:'手臂轻触椅背。'}];q.assets=[{id:'pose-asset',role:'pose',name:'姿态'}];q.$('pose-prompt').value='';q.api=async()=>{throw Error('must not create another analysis');};await q.restorePoseAnalysis('observation');assert.equal(q.$('pose-prompt').value,'手臂轻触椅背。');assert.equal(q.poseAssetId,'pose-asset');dom.window.close();});
test('empty sidebar references lead to the appropriate preparation step',opts,()=>{const {dom,q}=studio();q.renderSubmission();let destination;q.navigate=s=>destination=s;const body=q.$('reference-order').querySelector('[data-ref-role="body"]');assert.equal(body.disabled,false);body.click();assert.equal(destination,'person');assert.equal(q.view.person.role,'body');q.$('reference-order').querySelector('[data-ref-role="pose"]').click();assert.equal(destination,'lens');assert.equal(q.view.lens.sections.pose,true);dom.window.close();});

// Regression: the hero must not prefer a 512px cached medium over a local original.
test('shoot hero loads the local original and promotes a newly ready original without replacing film frames',opts,()=>{
 const {dom,q,w}=studio();try{
  q.assets=[{id:'work',role:'output',name:'清晰度测试',source:'generated',preview:'/preview.jpg',medium:'/medium.jpg',thumb:'/thumb.jpg'}];q.renderPhoto();
  const hero=q.$('studio-hero'),frame=q.$('studio-filmstrip').firstElementChild;
  assert.equal(hero.getAttribute('src'),'/preview.jpg');
  q.assets[0].original_url='/original.png';q.assets[0].original_size=[1776,2368];q.updateStudioCanvas();
  assert.equal(hero.getAttribute('src'),'/original.png');assert.equal(q.$('studio-filmstrip').firstElementChild,frame);
  assert.doesNotMatch(q.$('studio-quality-label').textContent,/本机原图/,'not ready before actual image load');
  Object.defineProperties(hero,{naturalWidth:{value:718,configurable:true},naturalHeight:{value:958,configurable:true}});hero.dispatchEvent(new w.Event('load'));
  assert.match(q.$('studio-quality-label').textContent,/本机原图/);assert.match(q.$('studio-quality-label').textContent,/1776.*2368/);
  q.assets[0].display_url='/adjusted.png';q.assets[0].adjusted=true;q.updateStudioCanvas();assert.equal(hero.getAttribute('src'),'/adjusted.png');
  hero.dispatchEvent(new w.Event('error'));assert.match(q.$('studio-quality-label').textContent,/失败/);assert.doesNotMatch(q.$('studio-quality-label').textContent,/本机原图/);
 }finally{dom.window.close();}
});
test('lens position and subject scale edit independently and only the active shot changes',opts,()=>{
 const {dom,q,w}=studio();try{
  q.changed=()=>{};q.step='lens';q.view.lens={sections:{camera:true}};q.renderLens();q.addShot();q.renderLens();
  const first=q.d().shots[0].prompt,hand='\n手写备注：保留衣领。';q.d().draft+=hand;q.d().shots[1].prompt=q.d().draft;
  const scale=q.$('stage').querySelector('[data-field="scale"][data-value*="以周围空间为主要画面"]');assert.ok(scale,'subject scale has its own control');scale.click();
  assert.match(w.PromptEngine.get(q.d().draft,'scale'),/自然余量/);assert.doesNotMatch(w.PromptEngine.get(q.d().draft,'scale'),/\d+%/);const value=w.PromptEngine.get(q.d().draft,'scale');
  q.$('stage').querySelector('[data-field="placement"][data-value="人物居中，构图稳定"]').click();
  assert.equal(w.PromptEngine.get(q.d().draft,'scale'),value);assert.equal(w.PromptEngine.get(q.d().draft,'placement'),'人物居中，构图稳定');
  assert.equal(q.d().shots[0].prompt,first);assert.match(q.d().shots[1].prompt,/手写备注：保留衣领/);assert.ok(q.shotChips(q.d().shots[1].prompt).includes('环境占比大'));
 }finally{dom.window.close();}
});

test('actual pixel zoom uses verified original dimensions when WebKit reports the decoded thumbnail size',opts,()=>{
 const {dom,q}=studio();try{
  q.assets=[{id:'wk',role:'output',name:'WebKit original',original_url:'/full.jpg',original_size:[1776,2368]}];q.openViewer('wk');
  const im=q.$('viewer-image');Object.defineProperties(im,{naturalWidth:{value:718},naturalHeight:{value:958}});
  q.viewerActual=true;q.zoomViewer(1);q.viewerInfo();assert.equal(im.style.width,'1776px');assert.equal(im.style.height,'2368px');
  assert.match(q.$('viewer-quality').textContent,/当前显示 1776 × 2368/);
 }finally{dom.window.close();}
});
